function validate([heights, bricks, ladders]) {
  if (!Array.isArray(heights) || heights.length < 1 || heights.length > 100000) return 'heights needs 1 to 10^5 values.';
  if (heights.some(h => !Number.isInteger(h) || h < 1 || h > 1000000)) return 'Each height is an integer from 1 to 10^6.';
  if (!Number.isInteger(bricks) || bricks < 0 || bricks > 1000000000) return 'bricks is an integer from 0 to 10^9.';
  if (!Number.isInteger(ladders) || ladders < 0 || ladders > heights.length) return 'ladders is from 0 to heights.length.';
  return null;
}

