function furthestBuilding(heights, bricks, ladders) {
  const heap = [];
  function push(value) {
    heap.push(value);
    let child = heap.length - 1;
    while (child > 0) {
      const up = (child - 1) >> 1;
      if (heap[up] <= heap[child]) break;
      [heap[up], heap[child]] = [heap[child], heap[up]];
      child = up;
    }
  }
  function popMin() {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let node = 0;
      while (true) {
        const left = 2 * node + 1;
        const right = left + 1;
        let small = node;
        if (left < heap.length && heap[left] < heap[small]) small = left;
        if (right < heap.length && heap[right] < heap[small]) small = right;
        if (small === node) break;
        [heap[small], heap[node]] = [heap[node], heap[small]];
        node = small;
      }
    }
    return top;
  }
  for (let i = 0; i < heights.length - 1; i++) {
    const climb = heights[i + 1] - heights[i];
    if (climb <= 0) {
      continue;
    }
    push(climb);
    if (heap.length > ladders) {
      bricks -= popMin();
    }
    if (bricks < 0) {
      return i;
    }
  }
  return heights.length - 1;
}

