function furthestBuilding(heights, bricks, ladders) {
  // Try every way of paying for each climb and keep the furthest index reached.
  const go = (i, b, l) => {
    if (i === heights.length - 1) return i;
    const climb = heights[i + 1] - heights[i];
    if (climb <= 0) return go(i + 1, b, l);
    let best = i;
    if (b >= climb) best = Math.max(best, go(i + 1, b - climb, l));
    if (l > 0) best = Math.max(best, go(i + 1, b, l - 1));
    return best;
  };
  return go(0, bricks, ladders);
}

