function generate(rand, size) {
  const big = size === 'large';
  const n = big ? 2000 : 1 + Math.floor(rand() * 9);
  const top = big ? 1000000 : [3, 10, 1000000][Math.floor(rand() * 3)];
  const heights = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  let rise = 0;
  for (let i = 0; i + 1 < n; i++) rise += Math.max(0, heights[i + 1] - heights[i]);
  // Give a random share of the total climbing, so the answer often lands in the middle.
  const bricks = Math.min(1000000000, Math.floor(rand() * rand() * (rise + 2)));
  const ladders = Math.floor(rand() * rand() * (n + 1));
  return [heights, bricks, ladders];
}
